/// <summary>
/// Chain-of-Command extension of <c>FormletterJournalCreate</c>.
/// Upgraded from the AX 2012 VAR-layer overlayering of <c>newPurchJournalCreate</c>
/// (marker: 08/04/2013-SSARAGOS-PSS-001-IMPORTFOLDER).
/// </summary>
[ExtensionOf(classStr(FormletterJournalCreate))]
final class PSSFormletterJournalCreate_Extension
{
}

Method.Source:
/// <summary>
/// Carries the PSS import folder reference from the posting contract onto the
/// packing slip journal creation class.
/// </summary>
/// <param name = "_formletterContract">The purchase form letter posting contract.</param>
/// <param name = "_parmTable">The posting parameter header record.</param>
/// <returns>The <c>FormletterJournalCreate</c> instance built by the standard chain.</returns>
public static FormletterJournalCreate newPurchJournalCreate(
    PurchFormLetterContract _formletterContract,
    VendDocumentTableMap    _parmTable)
{
    FormletterJournalCreate formletterJournalCreate = next newPurchJournalCreate(_formletterContract, _parmTable);

    // PSS-001 IMPORTFOLDER (AX 2012 VAR): only relevant when a packing slip journal is being created.
    if (isConfigurationkeyEnabled(configurationKeyNum(PSSImpFolder)))
    {
        PurchPackingSlipJournalCreate purchPackingSlipJournalCreate = formletterJournalCreate as PurchPackingSlipJournalCreate;

        if (purchPackingSlipJournalCreate)
        {
            purchPackingSlipJournalCreate.pssParmImpFolderTableRecId(_formletterContract.pssParmImpFolderTableRecId());
        }
    }

    return formletterJournalCreate;
}
